-- Versioned schema. Client table writes are denied: audited mutations use the RPC in 002.
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated, anon;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null default '' check(length(name)<=100),handle text unique check(handle ~ '^[a-z0-9_]{3,32}$'),institution text not null default '' check(length(institution)<=160),degree text not null default '' check(length(degree)<=100),bio text not null default '' check(length(bio)<=1200),interests text[] not null default '{}' check(cardinality(interests)<=20),methods text not null default '' check(length(methods)<=1000),equipment text not null default '' check(length(equipment)<=1000),available boolean not null default false,visibility text not null default 'members' check(visibility in('public','members','private')),membership text not null default 'not_submitted' check(membership in('not_submitted','pending','needs_evidence','approved','rejected','appeal','expired')),suspended boolean not null default false,phone_verified boolean not null default false,created_at timestamptz not null default now());
create table public.roles(user_id uuid references public.profiles(id) on delete cascade,role text check(role in('admin','reviewer','moderator','metadata_editor')),primary key(user_id,role));
create table public.membership_applications(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,institution text not null check(length(institution) between 2 and 160),degree text not null check(degree in('B.Tech / BE','M.Tech / ME / MS','PhD','Equivalent / combined')),discipline text not null check(length(discipline) between 3 and 200),result_status text not null check(result_status in('currently_enrolled','completed','awaiting_results')),year integer not null check(year between 1950 and 2100),private_marks text not null default '' check(length(private_marks)<=40),status text not null default 'pending' check(status in('pending','needs_evidence','approved','rejected','appeal','expired')),reason text not null default '' check(length(reason)<=1000),reviewer_id uuid references public.profiles(id) on delete set null,decided_at timestamptz,created_at timestamptz not null default now());
create table public.topics(name text primary key check(length(name) between 1 and 60));
create table public.preferences(user_id uuid primary key references public.profiles(id) on delete cascade,muted text[] not null default '{}' check(cardinality(muted)<=100),interests text[] not null default '{}' check(cardinality(interests)<=20),in_app boolean not null default true,email boolean not null default false,digest text not null default 'none' check(digest in('none','weekly')),language text not null default 'en' check(length(language)<=10));
create table public.blocks(user_id uuid references public.profiles(id) on delete cascade,target_id uuid references public.profiles(id) on delete cascade,check(user_id<>target_id),primary key(user_id,target_id));
create table public.follows(user_id uuid references public.profiles(id) on delete cascade,target_id uuid references public.profiles(id) on delete cascade,check(user_id<>target_id),primary key(user_id,target_id));
create table public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete restrict,title text not null check(length(title) between 8 and 180),problem text not null check(length(problem) between 20 and 6000),stage text not null check(length(stage) between 2 and 80),methods text not null default '' check(length(methods)<=3000),equipment text not null default '' check(length(equipment)<=1000),needs text not null default '' check(length(needs)<=1000),tags text[] not null check(cardinality(tags) between 1 and 8),visibility text not null default 'public' check(visibility in('public','private')),source_url text not null default '' check(source_url='' or (length(source_url)<=2048 and source_url ~ '^https://[^/@[:space:]]+([/?#]|$)')),license text not null default '' check(length(license)<=200),governance text not null check(length(governance) between 5 and 1000),archived boolean not null default false,created_at timestamptz not null default now());
create table public.project_members(project_id uuid references public.projects(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'Collaborator' check(length(role)<=80),primary key(project_id,user_id));
create table public.collaborations(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,message text not null check(length(message) between 10 and 2000),expertise text not null default '' check(length(expertise)<=1000),availability text not null default '' check(length(availability)<=200),status text not null default 'pending' check(status in('pending','accepted','declined')),created_at timestamptz not null default now());
create unique index collaboration_pending_unique on public.collaborations(project_id,sender_id) where status='pending';
create table public.papers(id text primary key check(length(id)<=250),doi text not null default '' check(length(doi)<=250),pmid text not null default '' check(pmid='' or pmid ~ '^[0-9]{1,12}$'),title text not null check(length(title) between 1 and 2000),authors text[] not null default '{}' check(cardinality(authors)<=30),venue text not null default '' check(length(venue)<=1000),published text not null default '' check(length(published)<=10),source text not null check(source in('Crossref','OpenAlex','PubMed','Member supplied')),source_url text not null check(length(source_url)<=2048 and source_url ~ '^https://[^/@[:space:]]+([/?#]|$)'),retrieved_at timestamptz not null,abstract_available boolean not null default false,correction text not null default '' check(length(correction)<=2000));
create unique index papers_doi_unique on public.papers(lower(doi)) where doi<>'';
create table public.paper_saves(user_id uuid references public.profiles(id) on delete cascade,paper_id text references public.papers(id) on delete cascade,primary key(user_id,paper_id));
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid references public.profiles(id) on delete cascade,kind text not null check(kind in('discussion','question','project_update','paper_discussion','resource')),title text not null check(length(title) between 8 and 180),body text not null check(length(body) between 20 and 10000),tags text[] not null check(cardinality(tags) between 1 and 8),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),visibility text not null check(visibility in('public','members','private')),state text not null default 'published' check(state in('published','removed')),project_id uuid references public.projects(id) on delete cascade,paper_id text references public.papers(id) on delete set null,source_url text not null default '' check(source_url='' or(length(source_url)<=2048 and source_url ~ '^https://[^/@[:space:]]+([/?#]|$)')),methods text not null default '' check(length(methods)<=3000),tried text not null default '' check(length(tried)<=3000),resolution text not null default '' check(length(resolution)<=3000),accepted_answer_id uuid,check(kind<>'project_update' or project_id is not null),check(kind<>'paper_discussion' or paper_id is not null or source_url<>''));
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body) between 5 and 6000),created_at timestamptz not null default now());
alter table public.posts add constraint posts_accepted_fk foreign key(accepted_answer_id) references public.comments(id) on delete set null;
create table public.reactions(user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,primary key(user_id,post_id));
create table public.bookmarks(user_id uuid references public.profiles(id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,primary key(user_id,post_id));
create table public.helpful(user_id uuid references public.profiles(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,primary key(user_id,comment_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,event_key text not null,category text not null,text text not null check(length(text)<=500),path text not null check(path ~ '^/(post|project|profile|settings|notifications)(/|$)'),read boolean not null default false,created_at timestamptz not null default now(),unique(user_id,event_key));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,post_id uuid not null references public.posts(id) on delete cascade,reason text not null check(length(reason) between 5 and 1000),status text not null default 'open' check(status in('open','reviewed')),created_at timestamptz not null default now());
create unique index report_open_unique on public.reports(reporter_id,post_id) where status='open';
create table public.contributions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,source_id uuid not null references public.comments(id) on delete cascade,kind text not null check(kind in('accepted_answer')),points integer not null check(points between 0 and 100),valid boolean not null default true,unique(source_id,kind));
create table public.audit(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,action text not null,target_id text not null,reason text not null check(length(reason) between 5 and 1000),created_at timestamptz not null default now());
create table private.action_receipts(user_id uuid references public.profiles(id) on delete cascade,request_id uuid,action text not null,created_at timestamptz not null default now(),primary key(user_id,request_id));
create table private.rate_limits(user_id uuid references public.profiles(id) on delete cascade,bucket text,window_start timestamptz not null default now(),hits integer not null default 1,primary key(user_id,bucket));
create table private.scholarly_cache(cache_key text primary key,response jsonb not null,expires_at timestamptz not null);
create index posts_cursor_idx on public.posts(created_at desc,id desc) where state='published';
create index posts_author_idx on public.posts(author_id);
create index posts_project_idx on public.posts(project_id,created_at desc);
create index posts_search_idx on public.posts using gin(to_tsvector('english',title||' '||body));
create index profiles_interests_idx on public.profiles using gin(interests);
create index comments_post_idx on public.comments(post_id,created_at);
create index notifications_user_idx on public.notifications(user_id,created_at desc);
create index projects_owner_idx on public.projects(owner_id);
create index project_members_user_idx on public.project_members(user_id,project_id);
create index applications_status_idx on public.membership_applications(status,created_at);

create function private.has_role(r text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.roles where user_id=auth.uid() and role=r)$$;
create function private.member() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and membership='approved' and not suspended)$$;
create function private.blocked(target uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.blocks where(user_id=auth.uid() and target_id=target)or(target_id=auth.uid() and user_id=target))$$;
create function private.project_read(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.projects p join public.profiles u on u.id=p.owner_id where p.id=pid and not private.blocked(p.owner_id) and((u.membership='approved' and not u.suspended and p.visibility='public')or(private.member() and(p.owner_id=auth.uid() or exists(select 1 from public.project_members m where m.project_id=p.id and m.user_id=auth.uid())))))$$;
create function private.post_read(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.posts p join public.profiles u on u.id=p.author_id where p.id=pid and p.state='published' and u.membership='approved' and not u.suspended and not private.blocked(p.author_id) and(p.project_id is null or private.project_read(p.project_id))and(p.visibility='public'or(private.member() and p.visibility='members')or(p.author_id=auth.uid() and p.visibility='private')))$$;
create function private.rate_limit(bucket_name text,max_hits integer) returns void language plpgsql security definer set search_path='' as $$declare count_hits integer;begin insert into private.rate_limits(user_id,bucket)values(auth.uid(),bucket_name)on conflict(user_id,bucket)do update set hits=case when private.rate_limits.window_start<now()-interval '1 minute' then 1 else private.rate_limits.hits+1 end,window_start=case when private.rate_limits.window_start<now()-interval '1 minute' then now() else private.rate_limits.window_start end returning hits into count_hits;if count_hits>max_hits then raise exception 'Rate limit exceeded';end if;end$$;
create function private.notify(target uuid,event text,cat text,msg text,destination text) returns void language sql security definer set search_path='' as $$insert into public.notifications(user_id,event_key,category,text,path)select target,event,cat,left(msg,500),destination where target<>auth.uid() and coalesce((select in_app from public.preferences where user_id=target),true)on conflict(user_id,event_key)do nothing$$;
create function private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,phone_verified)values(new.id,new.phone_confirmed_at is not null);return new;end$$;
create trigger auth_create_profile after insert on auth.users for each row execute function private.create_profile();
create function private.sync_phone() returns trigger language plpgsql security definer set search_path='' as $$begin update public.profiles set phone_verified=new.phone_confirmed_at is not null where id=new.id;return new;end$$;
create trigger auth_sync_phone after update of phone_confirmed_at on auth.users for each row execute function private.sync_phone();

-- All exposed application tables have RLS and only explicitly granted SELECT privileges.
do $$declare t text;begin foreach t in array array['profiles','roles','membership_applications','topics','preferences','blocks','follows','projects','project_members','collaborations','papers','paper_saves','posts','comments','reactions','bookmarks','helpful','notifications','reports','contributions','audit']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
grant select on public.profiles,public.posts,public.comments,public.projects,public.project_members,public.papers,public.topics,public.reactions,public.helpful to anon;
create policy profiles_read on public.profiles for select using(id=auth.uid()or private.has_role('admin')or(membership='approved' and not suspended and not private.blocked(id) and(visibility='public'or(visibility='members'and private.member()))));
create policy role_read on public.roles for select to authenticated using(user_id=auth.uid());
create policy applications_read on public.membership_applications for select to authenticated using(user_id=auth.uid()or private.has_role('reviewer')or private.has_role('admin'));
create policy topics_read on public.topics for select using(true);
create policy preferences_read on public.preferences for select to authenticated using(user_id=auth.uid());
create policy blocks_read on public.blocks for select to authenticated using(user_id=auth.uid());
create policy follows_read on public.follows for select to authenticated using(user_id=auth.uid());
create policy projects_read on public.projects for select using(private.project_read(id));
create policy project_members_read on public.project_members for select using(private.project_read(project_id));
create policy collaboration_read on public.collaborations for select to authenticated using(private.member() and not private.blocked(sender_id) and(sender_id=auth.uid()or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())));
create policy papers_read on public.papers for select using(true);
create policy paper_saves_read on public.paper_saves for select to authenticated using(user_id=auth.uid());
create policy posts_read on public.posts for select using(private.post_read(id)or((private.has_role('moderator')or private.has_role('admin'))and visibility<>'private'));
create policy comments_read on public.comments for select using(private.post_read(post_id) and not private.blocked(author_id));
create policy reactions_read on public.reactions for select using(private.post_read(post_id));
create policy bookmarks_read on public.bookmarks for select to authenticated using(user_id=auth.uid()and private.post_read(post_id));
create policy helpful_read on public.helpful for select using(exists(select 1 from public.comments c where c.id=comment_id));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy reports_read on public.reports for select to authenticated using(reporter_id=auth.uid()or private.has_role('moderator')or private.has_role('admin'));
create policy contribution_read on public.contributions for select to authenticated using(user_id=auth.uid());
create policy audit_read on public.audit for select to authenticated using(private.has_role('admin')or(private.has_role('reviewer')and action like 'membership_%')or(private.has_role('moderator')and action='moderate'));
revoke all on all functions in schema private from public;
grant execute on function private.has_role(text),private.member(),private.blocked(uuid),private.project_read(uuid),private.post_read(uuid) to authenticated,anon;
-- No client INSERT/UPDATE/DELETE grant or storage-write policy. Uploads fail closed until validation service exists.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('academic-evidence','academic-evidence',false,5242880,array['image/png','image/jpeg','application/pdf']),('project-files','project-files',false,5242880,array['image/png','image/jpeg','application/pdf']) on conflict(id)do nothing;
